ALTER TABLE public.org_suplencias ADD COLUMN IF NOT EXISTS rol_sustituido text NOT NULL DEFAULT 'responsable_sanitario', ADD COLUMN IF NOT EXISTS estado text NOT NULL DEFAULT 'pendiente de aceptación', ADD COLUMN IF NOT EXISTS categoria text NOT NULL DEFAULT 'otro', ADD COLUMN IF NOT EXISTS titular_user_id uuid, ADD COLUMN IF NOT EXISTS titular_nombre text, ADD COLUMN IF NOT EXISTS titular_cargo text, ADD COLUMN IF NOT EXISTS aceptada_en timestamptz, ADD COLUMN IF NOT EXISTS respondida_por uuid, ADD COLUMN IF NOT EXISTS terminada_en timestamptz, ADD COLUMN IF NOT EXISTS motivo_terminacion text;
CREATE INDEX IF NOT EXISTS org_suplencias_rol_vigencia ON public.org_suplencias(org_id,rol_sustituido,estado,fecha_fin);
CREATE OR REPLACE FUNCTION public.rol_efectivo(_usuario uuid,_rol public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
SELECT EXISTS(SELECT 1 FROM public.org_members m JOIN public.profiles p ON p.id=m.user_id AND p.activo WHERE m.org_id=public.get_user_org_id() AND m.user_id=_usuario AND (m.role=_rol OR (m.role<>'super_admin' AND _rol IN ('admin','responsable_sanitario') AND EXISTS(SELECT 1 FROM public.org_suplencias s JOIN public.org_members t ON t.org_id=s.org_id AND t.user_id=coalesce(s.titular_user_id,s.rs_titular_user_id) AND t.role::text=s.rol_sustituido JOIN public.profiles tp ON tp.id=t.user_id AND tp.activo WHERE s.org_id=m.org_id AND s.suplente_user_id=m.user_id AND s.rol_sustituido=_rol::text AND s.estado='activa' AND s.aceptada_en IS NOT NULL AND s.revocada_en IS NULL AND s.fecha_inicio<=now() AND now()<s.fecha_fin)))) $$;
REVOKE ALL ON FUNCTION public.rol_efectivo(uuid,public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rol_efectivo(uuid,public.app_role) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.rol_efectivo(_user_id,_role) OR EXISTS(SELECT 1 FROM public.org_members WHERE user_id=_user_id AND org_id=public.get_user_org_id() AND role='super_admin') $$;
CREATE OR REPLACE FUNCTION public.mis_roles_efectivos() RETURNS SETOF public.app_role LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT r FROM unnest(enum_range(NULL::public.app_role)) r WHERE public.rol_efectivo(auth.uid(),r) $$;
CREATE OR REPLACE FUNCTION public.puede_administrar_usuarios() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.rol_efectivo(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.org_members m JOIN public.profiles p ON p.id=m.user_id AND p.activo WHERE m.org_id=public.get_user_org_id() AND m.user_id=auth.uid() AND m.role='responsable_sanitario') $$;
REVOKE ALL ON FUNCTION public.mis_roles_efectivos(),public.puede_administrar_usuarios() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.mis_roles_efectivos(),public.puede_administrar_usuarios() TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.org_suplencias_acceso(_org uuid,_escritura boolean DEFAULT false) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE c record; BEGIN IF auth.uid() IS NULL THEN RETURN false;END IF;SELECT * INTO c FROM public.contexto_org_actual();IF c.org_id IS DISTINCT FROM _org THEN RETURN false;END IF;IF c.es_super_admin THEN RETURN NOT _escritura AND c.soporte_log_id IS NOT NULL;END IF;RETURN EXISTS(SELECT 1 FROM public.org_members m JOIN public.profiles p ON p.id=m.user_id AND p.activo WHERE m.org_id=_org AND m.user_id=auth.uid());END $$;
CREATE OR REPLACE FUNCTION public.org_suplencias_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE n text;c text;r text;BEGIN
IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Suplencias no se borran: terminar con motivo';END IF;
IF TG_OP='UPDATE' AND auth.uid() IS NULL AND auth.role()='service_role' AND current_setting('tracea.aviso_sistema',true)='resultado' THEN
IF (to_jsonb(NEW)-ARRAY['aviso_rs_enviado_en','aviso_rs_error','updated_at','updated_by']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['aviso_rs_enviado_en','aviso_rs_error','updated_at','updated_by']) THEN RAISE EXCEPTION 'Sistema solo registra resultado de aviso';END IF;NEW.updated_at:=now();NEW.updated_by:=NULL;RETURN NEW;END IF;
IF NOT public.org_suplencias_acceso(NEW.org_id,true) OR public.is_super_admin() THEN RAISE EXCEPTION 'Sin permiso para suplencias';END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(NEW.org_id::text,712));
IF TG_OP='INSERT' THEN
IF NEW.rol_sustituido NOT IN ('admin','responsable_sanitario') OR NEW.categoria NOT IN ('vacaciones','comisión','ausencia','otro') THEN RAISE EXCEPTION 'Rol o categoría inválidos';END IF;
IF NEW.fecha_fin<=NEW.fecha_inicio OR NEW.fecha_fin<=now() OR coalesce(btrim(NEW.motivo),'')='' THEN RAISE EXCEPTION 'Fechas válidas y motivo obligatorio';END IF;
SELECT m.role::text,p.nombre,p.cargo INTO r,n,c FROM public.org_members m JOIN public.profiles p ON p.id=m.user_id AND p.activo WHERE m.org_id=NEW.org_id AND m.user_id=NEW.titular_user_id;
IF r IS DISTINCT FROM NEW.rol_sustituido THEN RAISE EXCEPTION 'Titular no tiene el rol sustituido';END IF;
IF auth.uid()<>NEW.titular_user_id AND NOT public.rol_efectivo(auth.uid(),CASE WHEN NEW.rol_sustituido='admin' THEN 'responsable_sanitario'::public.app_role ELSE 'admin'::public.app_role END) THEN RAISE EXCEPTION 'Designa el titular o el otro rol con motivo';END IF;
NEW.titular_nombre:=n;NEW.titular_cargo:=c;
IF NEW.suplente_user_id=NEW.titular_user_id OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=NEW.suplente_user_id AND role='super_admin') OR EXISTS(SELECT 1 FROM public.org_members WHERE user_id=NEW.suplente_user_id AND role='super_admin') THEN RAISE EXCEPTION 'Suplente inválido';END IF;
SELECT p.nombre,p.cargo INTO n,c FROM public.org_members m JOIN public.profiles p ON p.id=m.user_id AND p.activo WHERE m.org_id=NEW.org_id AND m.user_id=NEW.suplente_user_id;
IF coalesce(btrim(n),'')='' OR coalesce(btrim(c),'')='' THEN RAISE EXCEPTION 'Suplente requiere membresía activa, nombre y cargo';END IF;
NEW.suplente_nombre:=n;NEW.suplente_cargo:=c;NEW.estado:='pendiente de aceptación';NEW.aceptada_en:=NULL;NEW.respondida_por:=NULL;NEW.terminada_en:=NULL;NEW.motivo_terminacion:=NULL;NEW.registrada_por:=auth.uid();NEW.created_by:=auth.uid();NEW.created_at:=now();NEW.revocada_en:=NULL;NEW.revocada_por:=NULL;
NEW.facultades:=ARRAY['autorizar','anular'];NEW.aviso_rs_requerido:=true;NEW.aviso_rs_enviado_en:=NULL;NEW.aviso_rs_error:=NULL;
ELSE
IF (to_jsonb(NEW)-ARRAY['estado','aceptada_en','respondida_por','terminada_en','motivo_terminacion','revocada_en','revocada_por','updated_at','updated_by']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['estado','aceptada_en','respondida_por','terminada_en','motivo_terminacion','revocada_en','revocada_por','updated_at','updated_by']) THEN RAISE EXCEPTION 'Designación e identidad inmutables';END IF;
NEW.aceptada_en:=OLD.aceptada_en;NEW.respondida_por:=OLD.respondida_por;NEW.terminada_en:=OLD.terminada_en;NEW.revocada_en:=OLD.revocada_en;NEW.revocada_por:=OLD.revocada_por;
IF OLD.estado='pendiente de aceptación' AND NEW.estado IN ('activa','rechazada') THEN
IF auth.uid()<>OLD.suplente_user_id OR OLD.fecha_fin<=now() OR OLD.revocada_en IS NOT NULL THEN RAISE EXCEPTION 'Solo el suplente responde una designación no vencida';END IF;
NEW.respondida_por:=auth.uid();NEW.aceptada_en:=CASE WHEN NEW.estado='activa' THEN now() ELSE NULL END;
IF NEW.estado='activa' AND EXISTS(SELECT 1 FROM public.org_suplencias s WHERE s.id<>NEW.id AND s.org_id=NEW.org_id AND s.rol_sustituido=NEW.rol_sustituido AND s.estado='activa' AND s.aceptada_en IS NOT NULL AND s.revocada_en IS NULL AND s.fecha_inicio<NEW.fecha_fin AND s.fecha_fin>NEW.fecha_inicio) THEN RAISE EXCEPTION 'Solo una suplencia vigente por rol';END IF;
IF NEW.estado='activa' AND NOT EXISTS(SELECT 1 FROM public.org_members m JOIN public.profiles p ON p.id=m.user_id AND p.activo WHERE m.org_id=NEW.org_id AND m.user_id=coalesce(NEW.titular_user_id,NEW.rs_titular_user_id) AND m.role::text=NEW.rol_sustituido) THEN RAISE EXCEPTION 'Titular ya no tiene el rol';END IF;
ELSIF OLD.estado IN ('pendiente de aceptación','activa') AND NEW.estado='terminada' THEN
IF auth.uid()<>coalesce(OLD.titular_user_id,OLD.rs_titular_user_id) AND auth.uid()<>OLD.suplente_user_id AND NOT public.rol_efectivo(auth.uid(),CASE WHEN OLD.rol_sustituido='admin' THEN 'responsable_sanitario'::public.app_role ELSE 'admin'::public.app_role END) THEN RAISE EXCEPTION 'Sin permiso para terminar';END IF;
IF coalesce(btrim(NEW.motivo_terminacion),'')='' THEN RAISE EXCEPTION 'Terminación requiere motivo';END IF;NEW.terminada_en:=now();NEW.revocada_en:=now();NEW.revocada_por:=auth.uid();
ELSE RAISE EXCEPTION 'Transición de suplencia no permitida';END IF;
END IF;
PERFORM set_config('tracea.motivo',CASE WHEN TG_OP='UPDATE' AND NEW.estado='terminada' THEN NEW.motivo_terminacion ELSE NEW.motivo END,true);
NEW.updated_by:=auth.uid();NEW.updated_at:=now();RETURN NEW;END $$;
CREATE OR REPLACE FUNCTION public.org_suplencia_titular_snapshot() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' AND NEW.rol_sustituido='responsable_sanitario' THEN NEW.rs_titular_user_id:=NEW.titular_user_id;NEW.rs_titular_nombre:=NEW.titular_nombre;NEW.rs_titular_cargo:=NEW.titular_cargo;ELSIF TG_OP='UPDATE' THEN NEW.rs_titular_user_id:=OLD.rs_titular_user_id;NEW.rs_titular_nombre:=OLD.rs_titular_nombre;NEW.rs_titular_cargo:=OLD.rs_titular_cargo;END IF;RETURN NEW;END $$;
CREATE OR REPLACE FUNCTION public.tend_suplencia(_org uuid,_facultad text) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT s.id FROM public.org_suplencias s WHERE _org=public.get_user_org_id() AND public.tend_acceso(_org,true) AND public.rol_efectivo(auth.uid(),'responsable_sanitario') AND s.org_id=_org AND s.suplente_user_id=auth.uid() AND s.rol_sustituido='responsable_sanitario' AND s.estado='activa' AND s.aceptada_en IS NOT NULL AND s.revocada_en IS NULL AND now()>=s.fecha_inicio AND now()<s.fecha_fin AND _facultad=ANY(s.facultades) LIMIT 1 $$;
CREATE OR REPLACE FUNCTION public.tend_firmante_autorizante(_org uuid,_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _org=public.get_user_org_id() AND public.rol_efectivo(_user,'responsable_sanitario') $$;
CREATE OR REPLACE FUNCTION public.tend_acceso(_org uuid,_escritura boolean DEFAULT false,_roles text[] DEFAULT NULL) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE c record;BEGIN IF auth.uid() IS NULL THEN RETURN false;END IF;SELECT * INTO c FROM public.contexto_org_actual();IF c.org_id IS DISTINCT FROM _org OR NOT public.mi_org_tiene_modulo('tendencias') OR NOT public.org_tiene_modulo(public.get_user_org_id(),'tendencias') THEN RETURN false;END IF;IF c.es_super_admin THEN RETURN NOT _escritura AND c.soporte_log_id IS NOT NULL;END IF;RETURN EXISTS(SELECT 1 FROM public.org_members m JOIN public.profiles p ON p.id=m.user_id AND p.activo WHERE m.org_id=_org AND m.user_id=auth.uid()) AND (_roles IS NULL OR EXISTS(SELECT 1 FROM unnest(_roles) r WHERE public.rol_efectivo(auth.uid(),r::public.app_role)));END $$;
CREATE OR REPLACE FUNCTION public.contexto_org_actual() RETURNS TABLE(org_id uuid,rol_en_org text,es_super_admin boolean,soporte_log_id uuid) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE v_sa boolean;v_log uuid;v_org uuid;v_rol text;BEGIN v_sa:=public.is_super_admin();IF v_sa THEN SELECT il.id INTO v_log FROM public.impersonation_logs il WHERE il.super_admin_id=auth.uid() AND il.ended_at IS NULL AND il.started_at>now()-interval '8 hours' ORDER BY il.started_at DESC LIMIT 1;END IF;v_org:=public.get_user_org_id();IF v_log IS NOT NULL THEN v_rol:='super_admin';ELSIF v_org IS NOT NULL THEN IF public.rol_efectivo(auth.uid(),'admin') THEN v_rol:='admin';ELSIF public.rol_efectivo(auth.uid(),'responsable_sanitario') THEN v_rol:='responsable_sanitario';ELSE SELECT m.role::text INTO v_rol FROM public.org_members m WHERE m.org_id=v_org AND m.user_id=auth.uid();END IF;END IF;RETURN QUERY SELECT v_org,v_rol,v_sa,v_log;END $$;
ALTER POLICY "Admins update same-org profiles" ON public.profiles USING(id=auth.uid() OR public.is_super_admin() OR (public.puede_administrar_usuarios() AND public.same_org_member(id))) WITH CHECK(id=auth.uid() OR public.is_super_admin() OR (public.puede_administrar_usuarios() AND public.same_org_member(id)));
CREATE OR REPLACE FUNCTION public.designar_suplencia(_rol public.app_role,_titular uuid,_suplente uuid,_inicio timestamptz,_fin timestamptz,_categoria text,_motivo text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v uuid;BEGIN INSERT INTO public.org_suplencias(org_id,rol_sustituido,titular_user_id,suplente_user_id,fecha_inicio,fecha_fin,categoria,motivo,facultades) VALUES(public.get_user_org_id(),_rol::text,_titular,_suplente,_inicio,_fin,_categoria,_motivo,ARRAY['autorizar','anular']) RETURNING id INTO v;RETURN v;END $$;
CREATE OR REPLACE FUNCTION public.responder_suplencia(_id uuid,_aceptar boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.org_suplencias SET estado=CASE WHEN _aceptar THEN 'activa' ELSE 'rechazada' END WHERE id=_id AND org_id=public.get_user_org_id() AND suplente_user_id=auth.uid();IF NOT FOUND THEN RAISE EXCEPTION 'Designación no disponible';END IF;END $$;
CREATE OR REPLACE FUNCTION public.terminar_suplencia(_id uuid,_motivo text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.org_suplencias SET estado='terminada',motivo_terminacion=_motivo WHERE id=_id AND org_id=public.get_user_org_id();IF NOT FOUND THEN RAISE EXCEPTION 'Designación no disponible';END IF;END $$;
REVOKE ALL ON FUNCTION public.designar_suplencia(public.app_role,uuid,uuid,timestamptz,timestamptz,text,text),public.responder_suplencia(uuid,boolean),public.terminar_suplencia(uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.designar_suplencia(public.app_role,uuid,uuid,timestamptz,timestamptz,text,text),public.responder_suplencia(uuid,boolean),public.terminar_suplencia(uuid,text) TO authenticated;
